__global__ void scan_kernel(const half* input, half* output, int total_elements, int scan_dim_size, int prefix_elements) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Shared memory for block-level scan
    extern __shared__ half shared_data[];

    // Each thread processes one element in the current batch
    for (int elem_offset = 0; elem_offset < scan_dim_size; elem_offset += blockDim.x) {
