        // Load data into shared memory
        if (elem_offset + tid < scan_dim_size) {
            shared_data[tid] = input[global_idx];
        } else {
            shared_data[tid] = __float2half(0.0f);
        }

        __syncthreads();

        // Up-sweep (reduce) phase
        for (int stride = 1; stride < blockDim.x; stride *= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < blockDim.x) {
                shared_data[index] += shared_data[index - stride];
            }
            __syncthreads();
        }

        // Down-sweep phase
        if (tid == 0) {
            shared_data[blockDim.x - 1] = __float2half(0.0f);
        }
        __syncthreads();

        for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < blockDim.x) {
                half temp = shared_data[index];
                shared_data[index] += shared_data[index - stride];
                shared_data[index - stride] = temp;
            }
            __syncthreads();
        }

        // Write back results
        if (elem_offset + tid < scan_dim_size) {
            output[global_idx] = shared_data[tid];
        }

        __syncthreads();
    }
}

// Optimized version for contiguous memory access
__global__ void scan_kernel_optimized(const half* input, half* output, int total_elements, int scan_dim_size, int prefix_elements) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    extern __shared__ half shared_data[];

    // Process elements in chunks
    int chunk_size = blockDim.x;
    int num_chunks = (scan_dim_size + chunk_size - 1) / chunk_size;

    half running_sum = __float2half(0.0f);

    for (int chunk = 0; chunk < num_chunks; ++chunk) {
        int start_idx = chunk * chunk_size;
        int end_idx = min(start_idx + chunk_size, scan_dim_size);

        // Load data into shared memory
        for (int i = tid; i < end_idx - start_idx; i += blockDim.x) {
            if (start_idx + i < scan_dim_size) {
                int global_idx = batch_idx * prefix_elements * scan_dim_size + start_idx + i;
                shared_data[i] = input[global_idx];
            }
        }
        __syncthreads();

        // Perform inclusive scan within the chunk
        for (int stride = 1; stride < chunk_size; stride *= 2) {
            if (tid >= stride && start_idx + tid < scan_dim_size) {
                int src_idx = start_idx + tid - stride;
                int dst_idx = start_idx + tid;
                shared_data[dst_idx] += shared_data[src_idx];
            }
            __syncthreads();
        }

        // Add previous running sum to current chunk
        for (int i = 0; i < end_idx - start_idx; i++) {
            if (start_idx + i < scan_dim_size) {
                int global_idx = batch_idx * prefix_elements * scan_dim_size + start_idx + i;
                output[global_idx] = shared_data[i] + running_sum;
            }
        }

        // Update running sum for next chunk
        if (end_idx - start_idx > 0 && tid == 0) {
            running_sum += shared_data[end_idx - start_idx - 1];
        }
        __syncthreads();
    }
