    const int block_size = 256;
    const int num_batches = total_elements / (prefix_elements * scan_dim_size);

    // Use optimized kernel for better performance
    size_t shared_mem_size = block_size * sizeof(half);
    scan_kernel_optimized<<<num_batches, block_size, shared_mem_size, stream>>>(
        input, output, total_elements, scan_dim_size, prefix_elements);
}
"""

# Python wrapper using torch.utils.cpp_extension
def create_scan_kernel():
    return load_inline(
        name="scan_kernel",
        cpp_sources=cuda_source,
        cuda_sources=cuda_source,
        functions=["launch_scan_kernel"],
        verbose=False
    )

